#define main old_main
#include "../reactor-protium/search.cpp"
#undef main
int main(){for(int i=0;i<N;i++){if(i%19)a[i].push_back(i-1);if(i%19<18)a[i].push_back(i+1);if(i>=19)a[i].push_back(i-19);if(i+19<N)a[i].push_back(i+19);}string filename=S("pvFile");if(filename.empty()){ifstream path("winner-path.txt");path>>filename;}if(filename.empty()){cerr<<"нет схемы: укажите файл или запустите поиск прибыли\n";return 2;}cerr<<"проверка "<<filename<<"\n";ifstream f(filename);Cand c;f>>c.power>>c.heat>>c.cool>>c.cost>>c.av>>c.hs>>c.ex>>c.re>>c.ch>>c.seed;string row;while(f>>row)c.g+=row;if((int)c.g.size()!=N){cerr<<"схема должна быть 19x16\n";return 2;}long long ticks=PI("pvTicks");ofstream out("validation.csv");out<<"order,cycle_gap,pass,max_V_fraction,max_C_fraction,max_hull_fraction,steady_gross_T,first_cycle_net_Qa,final_heat_B\n";
for(int order=0;order<4;order++)for(int gap=0;gap<2;gap++) {auto g=c.g;array<double,N>h{},cap{};array<int,128>n{};for(char x:g)n[x]++;double k=n['K'],p=n['P'],rate=M.rate0*(M.bEx+c.ex)*2*(1+M.capBoost*k),vr=M.vr0*(1+M.ventBoost*(M.bAv+c.av)*k),hc=M.hullPer*p,vc=M.vc0*(1+M.sinkBoost*(M.bHs+c.hs)*p),cc=M.ccap,sale=M.sales(k);
 int branches=0;for(int i=0;i<N;i++){cap[i]=g[i]=='V'?vc:g[i]=='C'?cc:g[i]=='K'?M.kcap:0;}for(int i=0;i<N;i++)if(g[i]=='O')for(int j:a[i])branches+=cap[j]>0;
 double hull=0,mv=0,mc=0,mh=0,sum=0,steady=0;bool ok=true;for(long long t=0;t<ticks;t++) {bool on=!gap||t<M.expStart||t>=M.expEnd;double power=0;double bonus=hull>0?M.boost(hull):1.;for(int i=0;i<N;i++)if(int co=core(g[i])){if(!on)continue;int pulse=co==1?1:co==2?4:12,refs=0,ns=0;for(int j:a[i]){pulse+=core(g[j]);refs+=g[j]=='R';ns+=cap[j]>0;}power+=pulse*M.fuelPow*(1+M.refl*refs)*bonus;double heat=pulse*pulse*M.fuelHeat/co;if(ns)for(int j:a[i])if(cap[j]>0)h[j]+=heat/ns;if(!ns)hull+=heat;}
 if(t<M.expStart)sum+=min(power,sale);if(t==M.expStart-100)steady=power;double flow=min(hull,branches*rate),per=flow/branches;
 auto outlet=[&](int i){for(int j:a[i])if(cap[j]>0){double q=min(per,hull);h[j]+=q;hull-=q;}};auto inlet=[&](int i){for(int j:a[i]){double q=min(rate,h[j]);h[j]-=q;hull+=q;}};
 if(order<2){for(int u=0;u<N;u++){int i=order?N-1-u:u;if(g[i]=='I')inlet(i);if(g[i]=='O')outlet(i);}}else{for(int i=0;i<N;i++)if(g[i]==(order==2?'O':'I')){if(order==2)outlet(i);else inlet(i);}for(int i=0;i<N;i++)if(g[i]==(order==2?'I':'O')){if(order==2)inlet(i);else outlet(i);}}
 for(int i=0;i<N;i++)if(g[i]=='V')h[i]=max(0.,h[i]-vr);for(int i=0;i<N;i++){if(cap[i]>0&&h[i]>=cap[i])ok=false;if(g[i]=='V')mv=max(mv,h[i]/vc);if(g[i]=='C')mc=max(mc,h[i]/cc);}mh=max(mh,hull/hc);if(hull>=hc)ok=false;hull=max(0.,hull-hc*M.drain);if(!ok)break;
 }double ht=hull;for(double x:h)ht+=x;out<<order<<','<<gap<<','<<ok<<','<<mv<<','<<mc<<','<<mh<<','<<steady/1000<<','<<sum/1e6-PR.fuel(n)<<','<<ht<<'\n';cout<<"порядок "<<order<<" пауза "<<gap<<": "<<(ok?"PASS":"FAIL")<<" Vent "<<mv<<" Coolant "<<mc<<" корпус "<<mh<<" мощность "<<steady/1000<<" T\n";}return 0;
}
